def visit_FromImport(self, node: nodes.FromImport, frame: Frame) -> None:
    """Visit named imports."""
    self.newline(node)
    prefix = self.temporary_identifier()
    self.writeline(f"{prefix} = ")
    self._import_common(node, frame)
    for name in node.names:
        if isinstance(name, tuple):
            name, alias = name
        else:
            alias = name
        msg = (
            f"the template {self.name!r} (imported on {self.position(node)})"
            f" does not export the requested name"
        )
        self.writeline(
            f"{frame.symbols.ref(alias)} = getattr({prefix}, {name!r}, "
            f"undefined({msg!r}))"
        )
        if frame.toplevel:
            self.writeline(f"context.vars[{alias!r}] = {frame.symbols.ref(alias)}")
        if frame.toplevel and not alias.startswith("_"):
            self.writeline(f"context.exported_vars.discard({alias!r})")

